"use client"

import { useState, useRef } from "react"
import { useToast } from "@/hooks/use-toast"
import { usePhotoBulkUploadStore } from "@/store/photo-bulk-upload.store"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import { Upload, FileSpreadsheet } from "lucide-react"

export default function PhotoBulkUploadPage() {
  const [file, setFile] = useState<File | null>(null)
  const [progress, setProgress] = useState(0)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const { upload, response, loading } = usePhotoBulkUploadStore()
  const { toast } = useToast()

  const handleUpload = async () => {
    if (!file) return

    setProgress(40)

    try {
      await upload(file)
      setProgress(100)

      toast({
        title: "Photo Bulk Upload Successful",
        description: response?.message,
      })
    } catch (err: any) {
      toast({
        variant: "destructive",
        title: "Upload Failed",
        description: err.message,
      })
    }
  }

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Upload className="w-5 h-5" />
            Student Photo Bulk Upload
          </CardTitle>
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="border-2 border-dashed rounded-lg p-8 text-center">
            <FileSpreadsheet className="w-10 h-10 mx-auto mb-3" />

            {file ? (
              <p className="mb-4 font-medium">{file.name}</p>
            ) : (
              <p className="mb-4">Select Excel/CSV File</p>
            )}

            <Button onClick={() => fileInputRef.current?.click()}>
              Choose File
            </Button>

            <input
              hidden
              ref={fileInputRef}
              type="file"
              onChange={(e) =>
                e.target.files && setFile(e.target.files[0])
              }
            />
          </div>

          {loading && <Progress value={progress} />}

          <Button
            onClick={handleUpload}
            disabled={!file || loading}
            className="w-full"
          >
            Upload Photos
          </Button>

          {response && (
            <div className="text-sm mt-4 space-y-1">
              <p>Total Rows: {response.total_rows}</p>
              <p>Updated: {response.updated_total}</p>
              <p>Errors: {response.errors_count}</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}
